import React from 'react';

/**
 * RichContentView safely renders HTML generated by ReactQuill.
 * If the content is empty or contains only empty tags (like <p><br></p>),
 * it renders the provided fallback.
 */
export const RichContentView = ({
    html = '',
    fallback = 'No details provided.',
    className = '',
    style = {}
}) => {
    if (!html) {
        return (
            <span style={{ color: '#94a3b8', fontStyle: 'italic', fontSize: '13px', ...style }}>
                {fallback}
            </span>
        );
    }

    const stripped = String(html).replace(/<[^>]*>?/gm, '').trim();
    if (!stripped && !html.includes('<img')) {
        return (
            <span style={{ color: '#94a3b8', fontStyle: 'italic', fontSize: '13px', ...style }}>
                {fallback}
            </span>
        );
    }

    return (
        <div
            className={`richContentBody ${className}`}
            style={{
                lineHeight: 1.6,
                fontSize: '13px',
                color: '#334155',
                wordBreak: 'break-word',
                ...style
            }}
            dangerouslySetInnerHTML={{ __html: html }}
        />
    );
};

/**
 * Helper to strip HTML tags for grid cells, tooltips, or compact summaries
 */
export const stripHtml = (html) => {
    if (!html) return '';
    return String(html)
        .replace(/<[^>]*>?/gm, ' ')
        .replace(/&nbsp;/g, ' ')
        .replace(/\s+/g, ' ')
        .trim();
};

export default RichContentView;

